function dropdownClass(lockState) {
  if (lockState === 'closing') return ' is-closing nav-dropdown-force-closed';
  if (lockState === 'closed') return ' is-closed nav-dropdown-force-closed';
  return '';
}

/** Close Programs / iBridge For after option click (React state survives re-renders). */
function useNavDropdownLock() {
  const [lock, setLock] = useState({});
  const timersRef = useRef({});

  const clearTimer = useCallback((id) => {
    if (timersRef.current[id]) {
      window.clearTimeout(timersRef.current[id]);
      delete timersRef.current[id];
    }
  }, []);

  const closeMenu = useCallback(
    (id) => {
      clearTimer(id);
      setLock((prev) => ({ ...prev, [id]: 'closing' }));
      timersRef.current[id] = window.setTimeout(() => {
        setLock((prev) => ({ ...prev, [id]: 'closed' }));
        delete timersRef.current[id];
      }, 240);

      if (document.activeElement instanceof HTMLElement) {
        document.activeElement.blur();
      }
      document.getElementById('ekit-megamenu-demo-menu')?.classList.remove('active');
      document.querySelector('.elementskit-menu-overlay')?.classList.remove('active');
      document.querySelector('.ekit-menu-overlay')?.classList.remove('active');
      document.body.classList.remove('mobile-nav-open');
      document.querySelectorAll('.elementskit-megamenu-has.elementskit-dropdown-open').forEach((openItem) => {
        openItem.classList.remove('elementskit-dropdown-open');
        openItem.querySelector('.elementskit-megamenu-panel')?.classList.remove('elementskit-dropdown-open');
      });
    },
    [clearTimer],
  );

  const unlockMenu = useCallback(
    (id) => {
      clearTimer(id);
      setLock((prev) => {
        if (!prev[id]) return prev;
        const next = { ...prev };
        delete next[id];
        return next;
      });
    },
    [clearTimer],
  );

  useEffect(
    () => () => {
      Object.values(timersRef.current).forEach((t) => window.clearTimeout(t));
    },
    [],
  );

  return { lock, closeMenu, unlockMenu };
}

